import { useEffect, useId, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent } from "react";

export type AlignmentItem = {
  id: string;
  name: string;
  position: { x: number; y: number } | null;
  /** Local PNG/JPEG/WebP data URL; no remote image fetch is performed. */
  imageDataUrl?: string;
};

export type AlignmentMatrixProps = {
  items: AlignmentItem[];
  onItemsChange: (items: AlignmentItem[]) => void;
  title?: string;
  leftLabel?: string;
  rightLabel?: string;
  topLabel?: string;
  bottomLabel?: string;
  allowImages?: boolean;
  showGrid?: boolean;
  readOnly?: boolean;
  maxItems?: number;
  className?: string;
};

const limit = (value: number) => Math.round(Math.max(0, Math.min(100, Number.isFinite(value) ? value : 50)));
const validImage = (value?: string) => value && /^data:image\/(png|jpeg|webp);base64,/i.test(value) ? value : undefined;

function Icon({ kind }: { kind: "plus" | "close" | "image" | "trash" }) {
  const paths = {
    plus: "M12 5v14M5 12h14",
    close: "m6 6 12 12M6 18 18 6",
    image: "M4 4h16v16H4zM4 16l5-5 4 4 3-3 4 4M15 8h.01",
    trash: "M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7",
  };
  return <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[kind]} /></svg>;
}

type Drag = { id: string; pointerId: number; startX: number; startY: number; moved: boolean; point: { x: number; y: number } | null };

export function AlignmentMatrix({
  items, onItemsChange, title = "Alignment matrix", leftLabel = "Familiar", rightLabel = "Unexpected",
  topLabel = "Expressive", bottomLabel = "Practical", allowImages = true, showGrid = true,
  readOnly = false, maxItems = 12, className = "",
}: AlignmentMatrixProps) {
  const uid = useId(), plot = useRef<HTMLDivElement>(null), entry = useRef<HTMLInputElement>(null);
  const drag = useRef<Drag | null>(null), suppressClick = useRef(false), reader = useRef<FileReader | null>(null);
  const latest = useRef({ items, onItemsChange, readOnly });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [name, setName] = useState(""), [status, setStatus] = useState(""), [imageError, setImageError] = useState("");
  const [preview, setPreview] = useState<{ id: string; point: { x: number; y: number } } | null>(null);
  const selected = items.find(item => item.id === selectedId);
  const capacity = Math.max(1, Math.min(50, Math.floor(maxItems) || 12));
  useEffect(() => { latest.current = { items, onItemsChange, readOnly }; }, [items, onItemsChange, readOnly]);
  useEffect(() => () => { const pending = reader.current; reader.current = null; pending?.abort(); }, []);
  useEffect(() => { if (readOnly) { drag.current = null; setPreview(null); } }, [readOnly]);

  function update(id: string, changes: Partial<AlignmentItem>) {
    if (readOnly) return;
    onItemsChange(items.map(item => item.id === id ? { ...item, ...changes } : item));
  }
  function cancelImageRead() { const pending = reader.current; reader.current = null; pending?.abort(); }
  function select(id: string | null) { cancelImageRead(); setSelectedId(id); setImageError(""); }
  function add() {
    const clean = name.trim();
    if (!clean || readOnly || items.length >= capacity) return;
    const id = crypto.randomUUID();
    onItemsChange([...items, { id, name: clean, position: null }]);
    select(id); setName(""); setStatus(clean + " added. Tap the matrix or set coordinates to place it."); entry.current?.focus();
  }
  function coordinates(clientX: number, clientY: number) {
    const rect = plot.current!.getBoundingClientRect();
    return { x: limit((clientX - rect.left) / rect.width * 100), y: limit((1 - (clientY - rect.top) / rect.height) * 100) };
  }
  function place(id: string, point: { x: number; y: number }) {
    update(id, { position: point }); select(id);
    setStatus((items.find(item => item.id === id)?.name || "Item") + " positioned at X " + point.x + ", Y " + point.y + ".");
  }
  function cancelDrag() { drag.current = null; setPreview(null); suppressClick.current = true; }
  function beginDrag(event: ReactPointerEvent<HTMLButtonElement>, item: AlignmentItem) {
    if (readOnly || !event.isPrimary || event.button !== 0) return;
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = { id: item.id, pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, moved: false, point: item.position };
    suppressClick.current = false;
  }
  function moveDrag(event: ReactPointerEvent<HTMLButtonElement>) {
    const active = drag.current;
    if (!active || active.pointerId !== event.pointerId) return;
    if (!active.moved && Math.hypot(event.clientX - active.startX, event.clientY - active.startY) < 6) return;
    active.moved = true; active.point = coordinates(event.clientX, event.clientY);
    setPreview({ id: active.id, point: active.point });
  }
  function endDrag(event: ReactPointerEvent<HTMLButtonElement>) {
    const active = drag.current;
    if (!active || active.pointerId !== event.pointerId) return;
    drag.current = null; setPreview(null);
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    if (active.moved && active.point) { place(active.id, active.point); suppressClick.current = true; }
  }
  function upload(file?: File) {
    cancelImageRead(); setImageError("");
    if (!file || !selected || readOnly) return;
    if (!["image/png", "image/jpeg", "image/webp"].includes(file.type) || file.size > 2 * 1024 * 1024) {
      setImageError("Choose a PNG, JPEG or WebP under 2 MB."); return;
    }
    const id = selected.id, nextReader = new FileReader(); reader.current = nextReader;
    nextReader.onerror = () => { if (reader.current === nextReader) setImageError("That image could not be read. Try another file."); };
    nextReader.onload = () => {
      if (reader.current !== nextReader) return;
      const data = String(nextReader.result), image = new Image();
      image.onerror = () => { if (reader.current === nextReader) setImageError("That file is not a readable image."); };
      image.onload = () => {
        if (reader.current !== nextReader || latest.current.readOnly) return;
        if (image.width > 4096 || image.height > 4096) { setImageError("Choose an image no larger than 4096 pixels on either side."); return; }
        const current = latest.current;
        if (!current.items.some(item => item.id === id)) return;
        current.onItemsChange(current.items.map(item => item.id === id ? { ...item, imageDataUrl: data } : item));
        setStatus("Image added locally. No upload was sent.");
      };
      image.src = data;
    };
    nextReader.readAsDataURL(file);
  }
  function dot(item: AlignmentItem) {
    const image = validImage(item.imageDataUrl);
    return <span className="am-avatar">{image ? <img src={image} alt="" draggable={false} /> : <span aria-hidden="true">{item.name.slice(0, 1).toUpperCase()}</span>}</span>;
  }

  return <section className={("am-root " + className).trim()} aria-labelledby={uid + "-title"} data-readonly={readOnly || undefined}>
    <style>{styles}</style>
    <header className="am-header"><div><p className="am-eyebrow">Map the relationship</p><h2 id={uid + "-title"}>{title}</h2></div><span className="am-count">{items.length} {items.length === 1 ? "item" : "items"}</span></header>
    {!readOnly && <div className="am-add">
      <label className="am-sr" htmlFor={uid + "-name"}>New item name</label>
      <input ref={entry} id={uid + "-name"} value={name} maxLength={80} placeholder="Name an idea, product or direction" onChange={event => setName(event.target.value)} onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); add(); } }} />
      <button className="am-primary am-icon" type="button" aria-label="Add item" title="Add item" disabled={!name.trim() || items.length >= capacity} onClick={add}><Icon kind="plus" /></button>
    </div>}
    <div className="am-items" aria-label="Matrix items">
      {items.map(item => <button type="button" className="am-chip" key={item.id} aria-pressed={selectedId === item.id} title={item.name} onClick={() => select(item.id)}>{dot(item)}<span className="am-chip-name">{item.name}</span>{!item.position && <span className="am-unplaced">Unplaced</span>}</button>)}
      {!items.length && <p className="am-help">Start with one idea. Add a name, then choose its place.</p>}
    </div>
    <p className="am-help" id={uid + "-help"}>{readOnly ? "Select an item to inspect its position." : "Select a name and tap the matrix, or drag a dot. Arrow keys move by 1; Shift moves by 10."}</p>
    <div className="am-frame">
      <span className="am-axis am-axis-top">{topLabel}</span><span className="am-axis am-axis-bottom">{bottomLabel}</span>
      <span className="am-axis am-axis-left">{leftLabel}</span><span className="am-axis am-axis-right">{rightLabel}</span>
      <div ref={plot} className="am-plot" data-grid={showGrid} role="group" aria-label="Alignment plot" aria-describedby={uid + "-help"} onClick={event => {
        if (readOnly || !selected || (event.target as Element).closest("button")) return;
        place(selected.id, coordinates(event.clientX, event.clientY));
      }}>
        <span className="am-center" aria-hidden="true">+</span>
        {items.map(item => {
          const point = preview?.id === item.id ? preview.point : item.position;
          if (!point) return null;
          const x = limit(point.x), y = limit(point.y);
          return <button key={item.id} type="button" className="am-point" data-dragging={preview?.id === item.id || undefined} aria-pressed={selectedId === item.id} aria-label={item.name + ", X " + x + ", Y " + y} style={{ left: x + "%", top: (100 - y) + "%", "--label-shift": x < 18 ? "0%" : x > 82 ? "-100%" : "-50%", "--label-left": x < 18 ? "0%" : x > 82 ? "100%" : "50%" } as CSSProperties}
            onPointerDown={event => beginDrag(event, item)} onPointerMove={moveDrag} onPointerUp={endDrag}
            onPointerCancel={cancelDrag} onLostPointerCapture={() => { if (drag.current?.id === item.id) cancelDrag(); }}
            onClick={() => { if (suppressClick.current) { suppressClick.current = false; return; } select(item.id); }}
            onKeyDown={event => {
              if (event.key === "Escape" && drag.current) { event.preventDefault(); cancelDrag(); return; }
              if (readOnly || !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) return;
              event.preventDefault();
              const step = event.shiftKey ? 10 : 1;
              place(item.id, { x: limit(x + (event.key === "ArrowLeft" ? -step : event.key === "ArrowRight" ? step : 0)), y: limit(y + (event.key === "ArrowDown" ? -step : event.key === "ArrowUp" ? step : 0)) });
            }}>{dot(item)}<span className="am-point-name" data-above={y < 14 || undefined}>{item.name}</span></button>;
        })}
      </div>
    </div>
    {selected && <div className="am-editor" aria-label="Selected item">
      <div className="am-editor-top"><span className="am-eyebrow">Selected item</span><button type="button" className="am-icon am-quiet" aria-label="Close item details" onClick={() => select(null)}><Icon kind="close" /></button></div>
      <div className="am-edit-fields">
        <label className="am-field am-name-field"><span>Name</span><input value={selected.name} maxLength={80} readOnly={readOnly} onChange={event => { if (event.target.value.trim()) update(selected.id, { name: event.target.value }); }} /></label>
        {(["x", "y"] as const).map(axis => <label className="am-field" key={axis}><span>{axis.toUpperCase()} · 0–100</span><input type="number" min={0} max={100} step={1} readOnly={readOnly} placeholder="—" value={selected.position?.[axis] ?? ""} onChange={event => {
          if (event.target.value === "" || !Number.isFinite(event.target.valueAsNumber)) return;
          update(selected.id, { position: { x: selected.position?.x ?? 50, y: selected.position?.y ?? 50, [axis]: limit(event.target.valueAsNumber) } });
        }} /></label>)}
      </div>
      {!readOnly && <div className="am-editor-actions">
        {allowImages && <label className="am-file am-button"><Icon kind="image" /><span>{selected.imageDataUrl ? "Replace image" : "Add image"}</span><input type="file" accept="image/png,image/jpeg,image/webp" aria-label="Choose item image" onChange={event => { upload(event.target.files?.[0]); event.target.value = ""; }} /></label>}
        {selected.imageDataUrl && allowImages && <button type="button" className="am-quiet am-button" onClick={() => { cancelImageRead(); update(selected.id, { imageDataUrl: undefined }); }}>Remove image</button>}
        {selected.position && <button type="button" className="am-quiet am-button" onClick={() => update(selected.id, { position: null })}>Unplace</button>}
        <button type="button" className="am-quiet am-icon am-remove" aria-label={"Remove " + selected.name} title="Remove item" onClick={() => {
          cancelImageRead(); onItemsChange(items.filter(item => item.id !== selected.id)); select(null); setStatus(selected.name + " removed."); entry.current?.focus();
        }}><Icon kind="trash" /></button>
      </div>}
      {imageError && <p className="am-error" role="alert">{imageError}</p>}
      {allowImages && !readOnly && <p className="am-help am-image-note">Images are read locally. PNG, JPEG or WebP · up to 2 MB.</p>}
    </div>}
    <p className="am-sr" role="status" aria-live="polite">{status}</p>
  </section>;
}

