import { useEffect, useState } from "react";
import { AlignmentMatrix, type AlignmentItem } from "@/components/ui/alignment-matrix";

const settings = {
  title: "Alignment matrix",
  leftLabel: "Familiar",
  rightLabel: "Unexpected",
  topLabel: "Expressive",
  bottomLabel: "Practical",
  allowImages: true,
  showGrid: true,
  readOnly: false,
};
const initialItems: AlignmentItem[] = [
  { id: "atlas", name: "Atlas", position: { x: 22, y: 68 } },
  { id: "morrow", name: "Morrow", position: { x: 73, y: 78 } },
  { id: "forma", name: "Forma", position: { x: 62, y: 25 } },
  { id: "kite", name: "Kite", position: { x: 20, y: 22 } },
];

export default function Demo(props: Partial<typeof settings>) {
  const [previewControls, setPreviewControls] = useState<{
    values: Partial<typeof settings>;
    remountToken: number;
  }>({ values: {}, remountToken: 0 });

  // Compatibility for 21st previews whose infrastructure does not forward controls.
  // Ordinary React hosts can still configure this demo directly through props.
  useEffect(() => {
    if (window.parent === window) return;
    const handleMessage = (event: MessageEvent) => {
      if (event.source !== window.parent) return;
      const data = event.data;
      if (!data || data.type !== "21st-controls:set") return;
      if (!data.values || typeof data.values !== "object" || Array.isArray(data.values)) return;
      const keys = Object.keys(settings) as (keyof typeof settings)[];
      const values = Object.fromEntries(keys
        .filter(key => Object.prototype.hasOwnProperty.call(data.values, key)
          && typeof data.values[key] === typeof settings[key])
        .map(key => [key, data.values[key]])) as Partial<typeof settings>;
      setPreviewControls({
        values,
        remountToken: Number.isSafeInteger(data.remountToken) && data.remountToken >= 0
          ? data.remountToken : 0,
      });
    };
    window.addEventListener("message", handleMessage);
    window.parent.postMessage({ type: "21st-controls:ready" }, "*");
    return () => window.removeEventListener("message", handleMessage);
  }, []);

  return <DemoContent {...props} {...previewControls.values} key={previewControls.remountToken} />;
}

